fn links() -> &'static Mutex<HashMap<String, Link>> {
    static L: OnceLock<Mutex<HashMap<String, Link>>> = OnceLock::new();
    L.get_or_init(|| Mutex::new(HashMap::new()))
}

fn source_id(node_id: &str) -> String {
    format!("mesh-{}", &node_id[..node_id.len().min(16)])
}

/// 给一台新设备分一个本地端口。已在册的沿用原端口(重试不换口,免得旧隧道占着不放)。
fn port_for(node_id: &str) -> u16 {
    let map = links().lock().unwrap();
    if let Some(l) = map.get(node_id) {
        return l.port;
    }
    let used: Vec<u16> = map.values().map(|l| l.port).collect();
    let mut p = PORT_BASE;
    while used.contains(&p) {
        p += 1;
    }
    p
}

// ────────────────────────────── 与云端目录通信 ──────────────────────────────

fn agent() -> ureq::Agent {
    ureq::AgentBuilder::new()
        .timeout_connect(CLOUD_TIMEOUT)
        .timeout_read(CLOUD_TIMEOUT)
        .build()
}

/// 把 ureq 错误翻成人话。云端明确给的业务错误原样透传(「设备已被移出设备网」这类
/// 必须让用户看见原文,糊成「网络错误」会让人对着正确的账号反复试)。
fn cloud_err(e: ureq::Error) -> String {
    match e {
        ureq::Error::Status(code, resp) => {
            let body = resp.into_string().unwrap_or_default();
            serde_json::from_str::<Value>(&body)
            gen,
            db_path: cur_db,
        },
    );
    Ok((user, device_id))
}

/// check_session 的落库部分(原逻辑不变,连接改走每线程复用的 with_conn)。
/// 返回 (用户, 设备标识, 会话到期时刻)。
fn check_session_db(token: &str, t: i64) -> Result<(User, String, i64), String> {
    db::with_conn(|conn| {
        let row = conn.query_row(
            "SELECT u.id,u.username,u.role,u.display_name,u.disabled,s.expires_at,s.device_id \
             FROM sessions s JOIN users u ON u.id=s.user_id WHERE s.token=?1",
            params![token],
            |r| {
                Ok((
                    r.get::<_, i64>(0)?,
                    r.get::<_, String>(1)?,
                    r.get::<_, String>(2)?,
                    r.get::<_, String>(3)?,
                    r.get::<_, i64>(4)?,
                    r.get::<_, i64>(5)?,
                    r.get::<_, String>(6)?,
                ))
            },
        );
        let (id, username, role, display_name, disabled, expires_at, device_id) =
            row.map_err(|_| "会话无效，请重新登录".to_string())?;
        if disabled != 0 {
            return Err("账号已停用".into());
        }
        if expires_at < t {
            let _ = conn.execute("DELETE FROM sessions WHERE token=?1", params![token]);
            return Err("会话已过期，请重新登录".into());
        }
        Ok((
            User {
                id,
                username,
                role,
                display_name,
                disabled: false,
            },
            device_id,
            expires_at,
        ))
    })
}

