//
// 「登录同一个账号 → 设备自己成网」的目录服务。只有账号权威(云机)提供;成员主机上这些
// 路由一律 400,与 /api/account/* 同口径。
//
// 鉴权是**设备密钥**(不是会话):Bearer mk_… 由 /api/mesh/enroll 颁发。理由是设备网的
// 心跳跑在后台、跨天跨重启,不该依赖某个会话的寿命;而它能做的事只有三样(报到、取本账号
// 设备清单、换一张 5 分钟身份断言),换不到任何一台设备的访问权。

/// 设备密钥入口闸。密钥无效/被吊销 → 403 并带上原因(客户端据此决定「重新入网」)。
// ───────────────────────── 设备信任契约 /api/peer/*(每台主机本地)─────────────────────────
//
// 与上面 /api/mesh/* 的分工要分清,这是整套设计的关键一刀:
//  · /api/mesh/*  在**云端**,回答「我有哪些设备」——目录,不含任何权限。
//  · /api/peer/*  在**本机**,回答「这台设备在我这儿能干什么」——权限,云端永远碰不到。
// 云机被完全拿下也改不动任何一台机器的 peer_grants:它根本没有这张表。

/// 本机的设备信任契约清单(owner 才看得到:这是权限面)。
async fn peer_grants_list(State(state): State<CollabState>, headers: HeaderMap) -> Response {
    let Some(ctx) = auth_ctx(&state, &headers).await else {
        return forbid();
    };
    if role_rank(&ctx.role) < 3 {
        return forbid();
    }
    let out = tokio::task::spawn_blocking(move || -> Result<Value, String> {
        let list: Vec<Value> = crate::collab::grants::list()?
            .into_iter()
            .map(|g| {
                json!({
                    "nodeId": g.node_id, "uid": g.uid, "name": g.name, "role": g.role,
                    "fsAccess": g.fs_access, "execAccess": g.exec_access,
                    // 实际生效的档(冷静期内会低于用户批的档)—— UI 要显示这个,
                    // 只显示库里那个会让用户以为「明明给了可写怎么写不进去」。
                    "effectiveFs": g.effective_fs(), "effectiveExec": g.effective_exec(),
                    "autoMount": g.auto_mount, "driveHint": g.drive_hint,
                    "cooldownUntil": g.cooldown_until, "inCooldown": g.in_cooldown(),
                    "grantedAt": g.granted_at, "grantedBy": g.granted_by, "revoked": g.revoked,
                })
            })
            .collect();
        Ok(json!({ "grants": list, "ownerUid": crate::collab::authority::owner_uid() }))
    })
    .await;
    unwrap_api(out)
}

/// 改一台设备的档位(盘 none/ro/rw、执行 none/ask/allow、自动挂载)。owner 才行。
async fn peer_grant_set(
    State(state): State<CollabState>,
    headers: HeaderMap,
    Json(v): Json<Value>,
) -> Response {
    let Some(ctx) = auth_ctx(&state, &headers).await else {
        return forbid();
    };
    if role_rank(&ctx.role) < 3 {
        return forbid();
    }
    let out = tokio::task::spawn_blocking(move || -> Result<Value, String> {
        let opt = |k: &str| v.get(k).and_then(|x| x.as_str()).map(|s| s.to_string());
        let g = crate::collab::grants::update(
            &s_of(&v, "nodeId"),
            opt("name").as_deref(),
            opt("fsAccess").as_deref(),
            opt("execAccess").as_deref(),
            v.get("autoMount").and_then(|x| x.as_bool()),
            &ctx.username,
        )?;
        Ok(json!({ "ok": true, "effectiveFs": g.effective_fs(), "autoMount": g.auto_mount }))
    })
    .await;
    unwrap_api(out)
}

/// 「信任这台设备」:冷静期立即清零(同时也把误撤销的恢复回来)。
async fn peer_grant_trust(
    State(state): State<CollabState>,
    headers: HeaderMap,
    Json(v): Json<Value>,
) -> Response {
    let Some(ctx) = auth_ctx(&state, &headers).await else {
        return forbid();
    };
    if role_rank(&ctx.role) < 3 {
        return forbid();
    }
    let out = tokio::task::spawn_blocking(move || -> Result<Value, String> {
        let g = crate::collab::grants::trust_fully(&s_of(&v, "nodeId"), &ctx.username)?;
        Ok(json!({ "ok": true, "effectiveFs": g.effective_fs() }))
    })
    .await;
    unwrap_api(out)
}

/// 撤销一台设备在**本机**的准入(丢了电脑 / 冷静期内反悔)。
///
/// 与云端的 `/api/mesh/revoke` 是两道独立的闸,应该都点:云端那道让它拿不到新断言,
/// 本机这道让它连断言都递不进来。云机被绕过、名册被伪造,本机这一行仍然说了算。
async fn peer_grant_revoke(
    State(state): State<CollabState>,
    headers: HeaderMap,
    Json(v): Json<Value>,
) -> Response {
    let Some(ctx) = auth_ctx(&state, &headers).await else {
        return forbid();
    };
    if role_rank(&ctx.role) < 3 {
        return forbid();
    }
    let out = tokio::task::spawn_blocking(move || -> Result<Value, String> {
        crate::collab::grants::revoke(&s_of(&v, "nodeId"), &ctx.username)?;
        Ok(json!({ "ok": true }))
    })
    .await;
    unwrap_api(out)
}

/// 把自己账号名下的一台设备移出设备网(丢了电脑的应急操作)。


// ───────────────────────── 远程文件写入(挂载盘的读写面)─────────────────────────
//
// 写比读危险一个量级 —— 远端能删你的文件。所以这批端点有**两道**独立的闸:
//  ① 角色闸:与读同一条线(owner 级)。挂载端拿的是同账号断言换来的本机会话。
//  ② 目录闸:fsface 逐根的写位。角色够了但目录没开写 → 一律拒。
// 两道都得过。少任何一道,「同账号自动组网」就变成「谁进得来谁就能删盘」。

/// 写端点共用的入口闸:角色或设备契约(见 [`fs_allowed`])。
/// 拒绝原因原样带出来 —— 「对方把这台设备设成了只读」必须显示成失败原因,
/// 糊成一句「需要 owner 权限」会让人对着正确的操作反复试。
async fn fs_write_guard(state: &CollabState, headers: &HeaderMap) -> Result<AuthCtx, String> {
    let ctx = auth_ctx(state, headers)
        .await
        .ok_or_else(|| "未授权".to_string())?;
    fs_allowed(&ctx, true)?;
    Ok(ctx)
}

/// fsface 的错误 → 403 + 原文。写失败的原因(只读/不在根内/父目录不存在)必须如实回给
/// 挂载端,资源管理器会把它显示成失败原因;糊成 500 就只剩一句「未指定的错误」。
fn fs_deny(e: String) -> Response {
    (StatusCode::FORBIDDEN, Json(json!({ "error": e }))).into_response()
}

/// 单个条目属性。挂载盘的 PROPFIND(文件)与 HEAD 走这条,省掉「列父目录再找一遍」。
async fn fs_stat_api(
    State(state): State<CollabState>,
    headers: HeaderMap,
    Query(q): Query<HashMap<String, String>>,
) -> Response {
    let Some(ctx) = auth_ctx(&state, &headers).await else {
        return forbid();
    };
    if let Err(e) = fs_allowed(&ctx, false) {
        return fs_deny(e);
    }
    let rel = q.get("path").cloned().unwrap_or_default();
    match tokio::task::spawn_blocking(move || crate::collab::fsface::stat(&rel)).await {
        Ok(Ok(e)) => Json(json!({ "entry": e })).into_response(),
        Ok(Err(e)) => fs_deny(e),
        Err(e) => err_resp(format!("内部任务失败: {e}")),
    }
}

/// 本机对远端开放了什么能力。挂载端据此决定盘挂成读写还是只读 ——
/// 不问就盲挂读写,用户会在资源管理器里拖进文件、等半天、再收一个「拒绝访问」。
                "errorCode": l.error_code,
                "lastVerifiedAt": l.last_verified_at,
                "error": l.err,
                // 对端会话 token 交给前端:远程终端(/api/exec)与「浏览盘」都靠它。
                // 与手工添加的远程源同一口径 —— 那条路的 owner 令牌本来就存在前端。
                "token": l.token.clone().unwrap_or_default(),
                "drive": m.and_then(|x| x.get("drive")).cloned().unwrap_or(json!("")),
                "writable": m.and_then(|x| x.get("writable")).cloned().unwrap_or(json!(false)),
                "ok": m.and_then(|x| x.get("ok")).cloned().unwrap_or(json!(false)),
            })
        })
        .collect();
    json!({
        "enrolled": enrolled,
        "ready": ready,
        "secure": secure,
        "enrollmentState": enrollment_state,
        "enrollmentWarn": enrollment_warn,
        "interconnect": orchestration::status(),
        "authorityConfigured": !default_authority().is_empty(),
        "configurationError": crate::collab::interconnect::load().err(),
        "relayConfig": orchestration::relay_status(),
        "url": meta(K_URL),
        "uid": visible_uid(),
        "nodeId": my_node_id(),
        "name": my_name(),
        "peers": peers,
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn url_normalization_prefers_https_and_public_http_requires_consent() {
        assert_eq!(norm_url(" example.com/ "), "https://example.com");
        assert_eq!(norm_url("https://a.com/"), "https://a.com");
        assert_eq!(norm_url("http://a.com"), "http://a.com");
        assert!(validate_authority_url("http://a.com", false)
            .unwrap_err()
            .contains("明文 HTTP"));
        assert_eq!(
            validate_authority_url("http://a.com", true).unwrap(),
            "http://a.com"
        );
        assert_eq!(
            validate_authority_url("http://127.0.0.1:8080", false).unwrap(),
            "http://127.0.0.1:8080"
        );
    }

    #[test]
    fn device_code_parser_requires_the_complete_plr1_shape() {
        let (code, node) = parse_device_code("plr1-abcd2345-node-identity").unwrap();
        assert_eq!(code, "ABCD2345");
        assert_eq!(node, "node-identity");
        assert!(parse_device_code("ABCD2345").is_err());
        assert!(parse_device_code("PLR1-ABCD2345").is_err());
        assert!(parse_device_code("PLR1--node").is_err());
        assert!(parse_device_code("PLRK1-old-owner-token")
            .unwrap_err()
            .starts_with("legacy_code_unsupported:"));
