// 信封与参数记账下沉契约层(polaris-protocol, 分仓规划 v2 第 1 仓种子):
// Args 记录分发代码实际读过哪些顶层参数, 没被读的 = 拼错名/契约漂移 —— 默认经
// `x-polaris-unknown-args` 响应头曝光, POLARIS_STRICT_ARGS=1 时直接 400。
use polaris_protocol::{strict_args_enabled, Args, InvokeRequest};

/// 把命令错误串按「客户端错误 vs 服务端错误」映射到合适的 HTTP 状态码,而非一律 500。
fn invoke_err_resp(e: String) -> Response {
    let status = if e.starts_with("未知命令") {
        StatusCode::NOT_FOUND
    } else if (e.contains("参数")
        && (e.contains("缺少") || e.contains("解析失败") || e.contains("无效")))
        // 非法枚举值(如 fable_search「mode 只接受 hybrid | grep | vector」)是客户端错误,
        // 此前落进兜底 500(spot-check 揪出错误分类)。
        || e.contains("只接受")
    {
        StatusCode::BAD_REQUEST
    } else if e.contains("(403)") {
        StatusCode::FORBIDDEN
    } else if e.contains("(404)") {
        StatusCode::NOT_FOUND
    } else if e.contains("(429)") {
        StatusCode::TOO_MANY_REQUESTS
    } else if e.contains("insufficient") || e.contains("余额") {
        // 上游供应商余额/额度失败(如云嵌入 403 account balance):外部依赖失败,
        // 非本服务端 bug。映射 502 让客户端提示「换供应商/充值」而非报「服务器崩了」。
        StatusCode::BAD_GATEWAY
    } else {
        StatusCode::INTERNAL_SERVER_ERROR
    };
    (status, Json(json!({ "error": e }))).into_response()
}
/// 「这台机器处于免口令模式，且**这一条请求**的来源够格」——由外壳(server.rs)按它
/// 自己那套来源判定算好，经请求扩展塞进来。没有这个扩展(桌面内嵌主机 / 老调用方)
/// 一律当 false。
///
/// 只有 [`collab_bootstrap`] 读它：免口令的 NAS 上机器根本没有口令可出示，
/// 不认这条闸就永远建不出第一个账号 —— 协作/团队整条线直接锁死。
/// 其余端点照旧只认真会话，`resolve_auth` 也绝不因此合成 owner。
#[derive(Clone, Copy, Debug)]
pub struct OpenGate(pub bool);

/// token(header 或 ws query) → AuthCtx。None = 未授权。
pub fn resolve_auth(auth_token: &Option<String>, token: Option<&str>) -> Option<AuthCtx> {
    // 轨② 全局口令 = owner。
    if let Some(expected) = auth_token.as_ref() {
        if token == Some(expected.as_str()) {
            return Some(AuthCtx {
                user_id: 0,
                username: "admin".into(),
                role: "owner".into(),
                device_id: String::new(),
            });
        }
    }
    // 轨① 会话 token。
    if let Some(t) = token {
        if let Ok((u, device_id)) = crate::collab::auth::check_session_with_device(t) {
            return Some(AuthCtx {
                user_id: u.id,
                username: u.username,
                role: u.role,
                device_id,
            });
        }
    }
    // 未命中就拒绝。零账号/无全局口令也绝不能合成 owner：否则攻击者可先调用
    // owner-only 的票据接口，再 redeem 绕过 bootstrap 初始化口令。
    None
}

/// header → AuthCtx。鉴权的同步 SQLite 查询挪进阻塞线程池:直接跑在 axum async worker
/// 上会钉住 reactor(会话短缓存命中时不落库,这层 spawn_blocking 兜的是未命中/首次)。
pub async fn auth_ctx(state: &CollabState, headers: &HeaderMap) -> Option<AuthCtx> {
    let auth_token = state.auth_token.clone();
    let token = bearer_of(headers);
    tokio::task::spawn_blocking(move || resolve_auth(&auth_token, token.as_deref()))
        .await
        .ok()
        .flatten()
}

